import{_ as s,c as a,b as e,o as p}from"./app-CAz8fl6k.js";const t={};function l(i,n){return p(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="视频播放器交互设计与性能优化-面试准备文档" tabindex="-1"><a class="header-anchor" href="#视频播放器交互设计与性能优化-面试准备文档"><span>视频播放器交互设计与性能优化 - 面试准备文档</span></a></h1><p>好，作为这个项目的开发者，我来以面试回答的方式，把 video.js 的集成设计讲清楚。</p><hr><h2 id="一、为什么选-video-js" tabindex="-1"><a class="header-anchor" href="#一、为什么选-video-js"><span>一、为什么选 video.js？</span></a></h2><p>这是一个<strong>抖音式的竖屏短剧播放器</strong>，核心需求：</p><ul><li>竖屏 9:16 视频播放</li><li>上下滑动切换视频（类似抖音）</li><li>需要进度条、静音切换、播放/暂停</li><li>移动端优先，必须支持 <code>playsinline</code>（iOS 内联播放）</li></ul><p>video.js 是开箱即用的选择：它有完整的控制栏、事件系统、插件生态，而且对移动端 H.264/MP4 兼容性很好。我不想从零写一个播放器。</p><hr><h2 id="二、cdn-加载策略-——-为什么不-npm-安装" tabindex="-1"><a class="header-anchor" href="#二、cdn-加载策略-——-为什么不-npm-安装"><span>二、CDN 加载策略 —— 为什么不 npm 安装？</span></a></h2><p>[这是最核心的设计决策]</p><p>你看 [index.html](file:///g:/Save/Grogramming/Vue3/yike/index.html#L6-L8)：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html"><pre><code class="language-html"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://vjs.zencdn.net/7.20.3/video-js.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://vjs.zencdn.net/7.20.3/video.min.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>三个原因：</strong></p><ol><li><p><strong>video.js 本体很大</strong>（压缩后约 500KB+）。如果是 SPA 首屏加载，会严重拖慢 FCP。走 CDN 可以利用浏览器缓存——用户访问过任何用 video.js CDN 的网站，这块就是 0 成本。</p></li><li><p><strong>Vite 的构建速度。</strong> video.js 是一个复杂的库，走 npm 构建时 Rollup 要处理大量 CommonJS 兼容和 polyfill，会拖慢开发时的 HMR。CDN 加载完全绕过了构建系统。</p></li><li><p><strong>与服务端视频流 CDN 同源策略无关。</strong> 视频流来自后端 API 返回的 CDN 地址（见 [handleVideo.js](file:///g:/Save/Grogramming/Vue3/yike/src/utils/handleVideo.js#L27-L33) 的 <code>getVideoAdd</code>），播放器和视频源是完全解耦的。</p></li></ol><p>代价是失去了 TypeScript 类型支持，所以我做了防御式判断：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code class="language-typescript"><span class="line"><span class="token comment">// PlayBar.vue onMounted 里</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> window<span class="token punctuation">.</span>videojs <span class="token operator">===</span> <span class="token string">&#39;undefined&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token builtin">console</span><span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&#39;video.js 未加载，请检查 CDN 引入&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、整体架构-三层设计" tabindex="-1"><a class="header-anchor" href="#三、整体架构-三层设计"><span>三、整体架构：三层设计</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌──────────────────────────────────────────────┐</span>
<span class="line">│                  Video.vue                    │  ← 滚动容器层</span>
<span class="line">│  管理 5 个视频队列                            │</span>
<span class="line">│  处理上下滑动 / 滚轮 / 键盘事件                │</span>
<span class="line">│                                              │</span>
<span class="line">│  ┌──────────┐ ┌──────────┐ ┌──────────┐     │</span>
<span class="line">│  │ PlayBar  │ │ PlayBar  │ │ PlayBar  │ ... │  ← 播放器实例层</span>
<span class="line">│  │ video.js │ │ video.js │ │ video.js │     │    每个都是独立播放器</span>
<span class="line">│  └──────────┘ └──────────┘ └──────────┘     │</span>
<span class="line">│        ↑           ↑           ↑            │</span>
<span class="line">│  ┌──────────────────────────────────────┐    │</span>
<span class="line">│  │        handleVideo.js                │    │  ← 队列管理层</span>
<span class="line">│  │  · 随机模式：预加载 15 个剧集元信息   │    │</span>
<span class="line">│  │  · 追剧模式：获取全部剧集(1000集)    │    │</span>
<span class="line">│  │  · 维护 5 个视频的播放队列           │    │</span>
<span class="line">│  └──────────────────────────────────────┘    │</span>
<span class="line">└──────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、核心组件-playbar-vue-——-单个播放器的完整封装" tabindex="-1"><a class="header-anchor" href="#四、核心组件-playbar-vue-——-单个播放器的完整封装"><span>四、核心组件：PlayBar.vue —— 单个播放器的完整封装</span></a></h2><p>[PlayBar.vue](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/PlayBar.vue#L254-L310) 是播放器的最小单元。</p><h3 id="_4-1-初始化配置" tabindex="-1"><a class="header-anchor" href="#_4-1-初始化配置"><span>4.1 初始化配置</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">player <span class="token operator">=</span> window<span class="token punctuation">.</span><span class="token function">videojs</span><span class="token punctuation">(</span>props<span class="token punctuation">.</span>videoInfo<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">height</span><span class="token operator">:</span> <span class="token string">&#39;1415&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">width</span><span class="token operator">:</span> <span class="token string">&#39;795.94&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">aspectRatio</span><span class="token operator">:</span> <span class="token string">&#39;9:16&#39;</span><span class="token punctuation">,</span>        <span class="token comment">// 竖屏比例</span></span>
<span class="line">    <span class="token literal-property property">controlBar</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">fullscreenToggle</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>   <span class="token comment">// 禁用全屏按钮</span></span>
<span class="line">        <span class="token literal-property property">playToggle</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>         <span class="token comment">// 禁用播放按钮（我们用点击画面控制）</span></span>
<span class="line">        <span class="token literal-property property">volumeMenuButton</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span>   <span class="token comment">// 禁用音量按钮（侧边栏自己控制）</span></span>
<span class="line">        <span class="token literal-property property">timeDivider</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">volumePanel</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">pictureInPictureToggle</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">remainingTimeDisplay</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">userAction</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">click</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">doubleClick</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">controls</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>设计思路：</strong> 这是一个极简的控制栏。video.js 默认的控制栏是为 16:9 横屏设计的，按钮太多。我把播放/暂停、音量、全屏全部禁用，只保留<strong>进度条</strong>——因为抖音式的交互是&quot;点击画面播放/暂停&quot;，&quot;侧边按钮控制静音&quot;。</p><h3 id="_4-2-点击与拖拽的冲突处理" tabindex="-1"><a class="header-anchor" href="#_4-2-点击与拖拽的冲突处理"><span>4.2 点击与拖拽的冲突处理</span></a></h3><p>这是一个很重要的细节。视频画面需要同时支持：</p><ul><li><strong>点击</strong> → 播放/暂停</li><li><strong>上下拖拽</strong> → 切换视频</li></ul><p>如果直接监听 <code>click</code> 事件，用户在滑动切换视频时手指抬起的瞬间也会触发 click。所以我用了一套&quot;位移阈值判断&quot;：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 伪代码逻辑</span></span>
<span class="line">onTouchStart → <span class="token function">记录起点</span> <span class="token punctuation">(</span>startX<span class="token punctuation">,</span> startY<span class="token punctuation">)</span></span>
<span class="line">onTouchMove  → 计算移动距离，距离 <span class="token operator">&gt;</span> 30px → 标记 isDragging <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">onTouchEnd   → 如果 <span class="token operator">!</span>isDragging → 这是点击，触发 播放<span class="token operator">/</span>暂停</span>
<span class="line">              如果 isDragging  → 这是滑动，交给 Video<span class="token punctuation">.</span>vue 处理切换</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>阈值设为 30px，小于这个距离的视为点击，大于的视为滑动。</p><h3 id="_4-3-事件监听与状态同步" tabindex="-1"><a class="header-anchor" href="#_4-3-事件监听与状态同步"><span>4.3 事件监听与状态同步</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">player<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&#39;play&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    dramaStore<span class="token punctuation">.</span><span class="token function">updateWatchRecord</span><span class="token punctuation">(</span>props<span class="token punctuation">.</span>vid<span class="token punctuation">,</span> props<span class="token punctuation">.</span>eid<span class="token punctuation">)</span>  <span class="token comment">// 播放时记录观看历史</span></span>
<span class="line">    isEnded<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">player<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&#39;ended&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    isEnded<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token boolean">true</span>    <span class="token comment">// 播完显示&quot;已结束&quot;遮罩</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>onVideoReady</code> 回调通过 <code>emit</code> 通知父组件 Video.vue：这个播放器准备好了。Video.vue 统计就绪数量，全部就绪后才隐藏 loading 页。</p><hr><h2 id="五、队列管理-handlevideo-js-——-5-视频滑动窗口" tabindex="-1"><a class="header-anchor" href="#五、队列管理-handlevideo-js-——-5-视频滑动窗口"><span>五、队列管理：handleVideo.js —— 5 视频滑动窗口</span></a></h2><p>[handleVideo.js](file:///g:/Save/Grogramming/Vue3/yike/src/utils/handleVideo.js) 是整个播放系统的引擎。</p><h3 id="_5-1-为什么是-5-个" tabindex="-1"><a class="header-anchor" href="#_5-1-为什么是-5-个"><span>5.1 为什么是 5 个？</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户正在看当前视频</span>
<span class="line">    ↑</span>
<span class="line">  上一个（预留在内存中，往回滑不卡）</span>
<span class="line">    ↑</span>
<span class="line">  当前 ← 正在播放</span>
<span class="line">    ↓</span>
<span class="line">  下一个（预加载，往下滑瞬间切换）</span>
<span class="line">    ↓</span>
<span class="line">  下下一个（预加载，再往下滑也不卡）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>5 个是一个平衡点：</p><ul><li>太少（如 3 个）→ 连续滑两次就没缓存了</li><li>太多（如 10 个）→ 5 个 <code>&amp;lt;video&amp;gt;</code> 标签同时存在内存压力大，而且 video.js 每个实例都有开销</li></ul><h3 id="_5-2-两种播放模式" tabindex="-1"><a class="header-anchor" href="#_5-2-两种播放模式"><span>5.2 两种播放模式</span></a></h3><p><strong>随机模式（首页 <code>/</code>）：</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">getRandomList(page=1, limit=15)  → 一次拿 15 集的元信息</span>
<span class="line">         ↓</span>
<span class="line">从 15 集中取出 5 个 → 逐个调 getVideoAdd 拿到真实播放地址</span>
<span class="line">         ↓</span>
<span class="line">维护 videoInfoList (长度=5)</span>
<span class="line">         ↓</span>
<span class="line">用户滑到底 → 重新取 15 集 → 再取 5 个</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追剧模式（<code>/play/:vid/:eid</code>）：</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">getAllEpisode(vid, limit=1000) → 一次拿该剧全部 1000 集</span>
<span class="line">         ↓</span>
<span class="line">按 eid 过滤 → 只保留 &gt;= 当前 eid 的剧集</span>
<span class="line">         ↓</span>
<span class="line">从过滤后的列表取 5 集 → 逐个拿播放地址</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-已知性能问题" tabindex="-1"><a class="header-anchor" href="#_5-3-已知性能问题"><span>5.3 已知性能问题</span></a></h3><p><code>handleVideo.js</code> 里有一个明显的优化点——<strong>视频地址是串行获取的</strong>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span>videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> <span class="token constant">VIDEO_LIST_LENGTH</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> videoInfo <span class="token operator">=</span> <span class="token keyword">await</span> randomList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> add <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getVideoAdd</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">.</span>eid<span class="token punctuation">)</span>   <span class="token comment">// ← 一个一个等</span></span>
<span class="line">    videoInfo<span class="token punctuation">.</span>url2 <span class="token operator">=</span> add</span>
<span class="line">    videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这意味着 5 个视频地址要等 5 次网络往返。如果改成 <code>Promise.all</code>，可以并行请求，理论上快 5 倍。当时写的时候优先保证功能正确性，这是后续优化的 TODO。</p><hr><h2 id="六、video-vue-——-竖屏滑动容器" tabindex="-1"><a class="header-anchor" href="#六、video-vue-——-竖屏滑动容器"><span>六、Video.vue —— 竖屏滑动容器</span></a></h2><p>[Video.vue](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/Video.vue) 作为外层容器，负责：</p><ol><li><strong>维护 <code>curIndex</code></strong>：当前正在播放的视频在队列中的索引</li><li><strong>触摸/鼠标/滚轮/键盘事件</strong>：<code>touchstart/move/end</code>、<code>mousedown/move/up</code>、<code>wheel</code>、<code>ArrowUp/ArrowDown</code></li><li><strong>滑动判断</strong>：累计位移超过 80px 触发切换，否则回弹</li><li><strong><code>scrollTo({ behavior: &#39;smooth&#39; })</code></strong> 实现丝滑切换</li><li><strong>Loading 状态管理</strong>：通过 <code>videosIsReady</code> 计算属性，等所有 PlayBar 都 emit <code>onVideoReady</code> 后才隐藏 loading</li></ol><h3 id="_6-1-切换逻辑" tabindex="-1"><a class="header-anchor" href="#_6-1-切换逻辑"><span>6.1 切换逻辑</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 触摸结束</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>offsetY <span class="token operator">&gt;</span> <span class="token number">80</span><span class="token punctuation">)</span>   → <span class="token function">prev</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 上滑 → 上一个视频</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>offsetY <span class="token operator">&lt;</span> <span class="token operator">-</span><span class="token number">80</span><span class="token punctuation">)</span>  → <span class="token function">next</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 下滑 → 下一个视频</span></span>
<span class="line"><span class="token keyword">else</span>                → <span class="token function">scrollToCurrent</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 回弹</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-滚动容器的-css" tabindex="-1"><a class="header-anchor" href="#_6-2-滚动容器的-css"><span>6.2 滚动容器的 CSS</span></a></h3><div class="language-scss line-numbers-mode" data-highlighter="prismjs" data-ext="scss"><pre><code class="language-scss"><span class="line"><span class="token selector">.video-container </span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">height</span><span class="token punctuation">:</span> 100vh<span class="token punctuation">;</span></span>
<span class="line">    <span class="token property">overflow</span><span class="token punctuation">:</span> scroll<span class="token punctuation">;</span></span>
<span class="line">    <span class="token property">scrollbar-width</span><span class="token punctuation">:</span> none<span class="token punctuation">;</span>           <span class="token comment">// Firefox 隐藏滚动条</span></span>
<span class="line">    <span class="token selector"><span class="token parent important">&amp;</span>::-webkit-scrollbar </span><span class="token punctuation">{</span> <span class="token property">display</span><span class="token punctuation">:</span> none<span class="token punctuation">;</span> <span class="token punctuation">}</span>  <span class="token comment">// Chrome 隐藏滚动条</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这是一个<strong>原生滚动容器</strong>，不是一个虚拟滚动（那是 TreeDemo 那边的东西）。5 个 PlayBar 各占 100vh，通过 <code>scrollTop</code> 切换。</p><hr><h2 id="七、样式定制-——-覆盖-video-js-默认皮肤" tabindex="-1"><a class="header-anchor" href="#七、样式定制-——-覆盖-video-js-默认皮肤"><span>七、样式定制 —— 覆盖 video.js 默认皮肤</span></a></h2><p>[play.scss](file:///g:/Save/Grogramming/Vue3/yike/src/styles/play.scss) 覆盖了 video.js 的默认样式：</p><div class="language-scss line-numbers-mode" data-highlighter="prismjs" data-ext="scss"><pre><code class="language-scss"><span class="line"><span class="token selector">.vjs-control-bar </span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">background-color</span><span class="token punctuation">:</span> <span class="token function">rgba</span><span class="token punctuation">(</span>255<span class="token punctuation">,</span> 0<span class="token punctuation">,</span> 0<span class="token punctuation">,</span> 0<span class="token punctuation">)</span> <span class="token important">!important</span><span class="token punctuation">;</span>  <span class="token comment">// 透明背景</span></span>
<span class="line">    <span class="token selector">.vjs-progress-holder </span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">background-color</span><span class="token punctuation">:</span> <span class="token function">rgba</span><span class="token punctuation">(</span>255<span class="token punctuation">,</span> 255<span class="token punctuation">,</span> 255<span class="token punctuation">,</span> 0.25<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 半透明白底</span></span>
<span class="line">        <span class="token property">border-radius</span><span class="token punctuation">:</span> 50px<span class="token punctuation">;</span>                           <span class="token comment">// 圆角进度条</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token selector">.vjs-play-progress.vjs-slider-bar </span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">border-radius</span><span class="token punctuation">:</span> 50px<span class="token punctuation">;</span>                           <span class="token comment">// 播放进度圆角</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token selector">.vjs-poster </span><span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">filter</span><span class="token punctuation">:</span> <span class="token function">blur</span><span class="token punctuation">(</span>3px<span class="token punctuation">)</span><span class="token punctuation">;</span>                             <span class="token comment">// 海报模糊效果</span></span>
<span class="line">        <span class="token property">transform</span><span class="token punctuation">:</span> <span class="token function">scale</span><span class="token punctuation">(</span>1.05<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>设计意图：抖音风的控制栏是<strong>透明底 + 圆角进度条</strong>，完全不同于 video.js 默认的深色半透明条。<code>!important</code> 是不得已——video.js 的默认样式优先级很高。</p><hr><h2 id="八、整体数据流" tabindex="-1"><a class="header-anchor" href="#八、整体数据流"><span>八、整体数据流</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">用户操作（滑动/点击）</span>
<span class="line">       │</span>
<span class="line">       ▼</span>
<span class="line">  Video.vue (curIndex 变化)</span>
<span class="line">       │</span>
<span class="line">       ├─→ 通过 props.Playing 告诉 PlayBar 是否播放</span>
<span class="line">       │</span>
<span class="line">       └─→ scrollToCurrent() 滚动到对应视频</span>
<span class="line">              │</span>
<span class="line">              ▼</span>
<span class="line">         PlayBar 收到 Playing prop</span>
<span class="line">              │</span>
<span class="line">              ├─ true  → player.play()</span>
<span class="line">              └─ false → player.pause()</span>
<span class="line">                    │</span>
<span class="line">                    ▼</span>
<span class="line">              video.js 实例控制 &lt;video&gt; 标签</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结-三个关键设计决策" tabindex="-1"><a class="header-anchor" href="#总结-三个关键设计决策"><span>总结：三个关键设计决策</span></a></h2><table><thead><tr><th>决策</th><th>选择</th><th>原因</th></tr></thead><tbody><tr><td>加载方式</td><td>CDN 而非 npm</td><td>减小打包体积、利用浏览器缓存、避开构建兼容问题</td></tr><tr><td>队列大小</td><td>5 个视频</td><td>内存与流畅度的平衡点</td></tr><tr><td>控制栏</td><td>只保留进度条</td><td>抖音式交互——点击画面控制播放，侧边按钮控制静音</td></tr></tbody></table><p>每个决策都是为&quot;抖音式竖屏短剧体验&quot;这个目标服务的。不是 video.js 的默认用法，而是根据产品需求做了大量裁剪和定制。</p><p>好的，这个问题问得非常到位，直接涉及到视频类产品的<strong>核心体验策略</strong>。让我结合这个项目的实际做法和业界通用原则来讲。</p><hr><h2 id="这个项目的做法-先加载-壳-再加载-肉" tabindex="-1"><a class="header-anchor" href="#这个项目的做法-先加载-壳-再加载-肉"><span>这个项目的做法：先加载&quot;壳&quot;，再加载&quot;肉&quot;</span></a></h2><p>看 [Video.vue](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/Video.vue#L242-L260) 的模板部分：</p><div class="language-vue line-numbers-mode" data-highlighter="prismjs" data-ext="vue"><pre><code class="language-vue"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>Transition</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>KeepAlive</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loading-page<span class="token punctuation">&quot;</span></span> <span class="token attr-name">v-if</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>!videosIsReady<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>LoadingPage</span> <span class="token punctuation">/&gt;</span></span></span>
<span class="line">        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>KeepAlive</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>Transition</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>PlayBar</span></span>
<span class="line">    <span class="token attr-name">v-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>(video, index) in videoInfoList<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:key</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>video.eid<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">:Playing</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>index == curIndex<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">...</span></span>
<span class="line"><span class="token punctuation">/&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以及就绪判断逻辑（[Video.vue#L297-L307](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/Video.vue#L297-L307)）：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> videosIsReady <span class="token operator">=</span> <span class="token function">computed</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span></span>
<span class="line">        readyVideoNum<span class="token punctuation">.</span>value <span class="token operator">&gt;=</span> videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length <span class="token operator">&amp;&amp;</span></span>
<span class="line">        videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length <span class="token operator">!=</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span></span>
<span class="line">        <span class="token operator">!</span>isRequiring<span class="token punctuation">.</span>value</span>
<span class="line">    <span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">handleVideoReady</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    readyVideoNum<span class="token punctuation">.</span>value <span class="token operator">+=</span> e</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>这个流程是：</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">1. Video.vue created → 立即渲染 LoadingPage（壳）</span>
<span class="line">                        ↓</span>
<span class="line">2. onBeforeMount → requireNew() 发起 API 请求拿数据</span>
<span class="line">                        ↓</span>
<span class="line">3. 数据返回 → videoInfoList 填充 → 渲染 5 个 PlayBar 组件</span>
<span class="line">                        ↓</span>
<span class="line">4. 每个 PlayBar mounted → 初始化 video.js → player ready</span>
<span class="line">                        ↓</span>
<span class="line">5. emit(&#39;onVideoReady&#39;) → readyVideoNum++ → 全部就绪?</span>
<span class="line">                        ↓ 是</span>
<span class="line">6. videosIsReady = true → LoadingPage 隐藏 → 视频画面出现</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>结论：UI 壳（Loading + 播放器容器）先出来，视频流最后加载。</strong></p><hr><h2 id="业界通用的加载策略-分层渲染" tabindex="-1"><a class="header-anchor" href="#业界通用的加载策略-分层渲染"><span>业界通用的加载策略：分层渲染</span></a></h2><p>几乎所有成熟的视频产品都遵循这个层次：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌──────────────────────────────────────────┐</span>
<span class="line">│  第 1 层：UI 壳（立即渲染）               │</span>
<span class="line">│  · 导航栏、侧边按钮、底部信息栏           │</span>
<span class="line">│  · 播放器容器（黑色背景占位）             │</span>
<span class="line">│  · Loading 动画 / 骨架屏                  │</span>
<span class="line">│  · 海报图（poster）                       │</span>
<span class="line">├──────────────────────────────────────────┤</span>
<span class="line">│  第 2 层：封面图（最快到达）              │</span>
<span class="line">│  · video.js 的 poster 属性                │</span>
<span class="line">│  · 或者一个独立的 &lt;img&gt; 标签              │</span>
<span class="line">│  · 通常用 CDN，秒加载                     │</span>
<span class="line">├──────────────────────────────────────────┤</span>
<span class="line">│  第 3 层：播放器 SDK 初始化               │</span>
<span class="line">│  · video.js / hls.js / shaka-player 等   │</span>
<span class="line">│  · 创建 MediaSource / MSE 实例            │</span>
<span class="line">├──────────────────────────────────────────┤</span>
<span class="line">│  第 4 层：视频首帧（最关键）              │</span>
<span class="line">│  · 发起网络请求获取视频流                 │</span>
<span class="line">│  · 解码第一帧 → 用户看到画面动起来了      │</span>
<span class="line">└──────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>核心原则一句话：让用户&quot;看到东西&quot;的延迟尽可能短，视频数据是最后一步。</strong></p><hr><h2 id="为什么要这样分层" tabindex="-1"><a class="header-anchor" href="#为什么要这样分层"><span>为什么要这样分层？</span></a></h2><h3 id="_1-心理感知时间" tabindex="-1"><a class="header-anchor" href="#_1-心理感知时间"><span>1. 心理感知时间</span></a></h3><table><thead><tr><th>策略</th><th>用户感受</th></tr></thead><tbody><tr><td>白屏 → 等 3 秒 → 视频出现</td><td>&quot;卡死了，关掉&quot;</td></tr><tr><td>骨架屏 → 封面图(0.5s) → 封面变视频(2s)</td><td>&quot;挺快的，已经在播了&quot;</td></tr></tbody></table><p><strong>白屏是最差的体验</strong>，因为它让用户觉得&quot;什么都没发生&quot;。Loading 动画或骨架屏告诉用户&quot;正在加载中，请稍等&quot;。</p><h3 id="_2-这个项目的-poster-策略" tabindex="-1"><a class="header-anchor" href="#_2-这个项目的-poster-策略"><span>2. 这个项目的 poster 策略</span></a></h3><p>看 [PlayBar.vue](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/PlayBar.vue#L477-L487)：</p><div class="language-vue line-numbers-mode" data-highlighter="prismjs" data-ext="vue"><pre><code class="language-vue"><span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span></span>
<span class="line">    <span class="token attr-name">:poster</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>props.img<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">preload</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>auto<span class="token punctuation">&quot;</span></span></span>
<span class="line">    <span class="token attr-name">muted</span></span>
<span class="line"><span class="token punctuation">&gt;</span></span></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>source</span> <span class="token attr-name">:src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>props.url2<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>video/mp4<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>poster</code> 是封面图，<code>preload=&quot;auto&quot;</code> 告诉浏览器尽可能提前下载视频。当用户看到封面图的时候，视频数据已经在后台加载了。封面图是一张小图片（通常几十 KB），而视频是几十 MB——<strong>小的先到，大的后到</strong>。</p><p>再看 [play.scss](file:///g:/Save/Grogramming/Vue3/yike/src/styles/play.scss)：</p><div class="language-scss line-numbers-mode" data-highlighter="prismjs" data-ext="scss"><pre><code class="language-scss"><span class="line"><span class="token selector">.vjs-poster </span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">filter</span><span class="token punctuation">:</span> <span class="token function">blur</span><span class="token punctuation">(</span>3px<span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// 海报模糊</span></span>
<span class="line">    <span class="token property">transform</span><span class="token punctuation">:</span> <span class="token function">scale</span><span class="token punctuation">(</span>1.05<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 略微放大</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>封面图做了模糊处理，这样当视频首帧出现时，<strong>从模糊到清晰的过渡</strong>有一种&quot;对焦完成&quot;的感觉，比直接从黑屏跳到清晰画面自然得多。这是短视频产品常用的手法。</p><h3 id="_3-数据获取的时序" tabindex="-1"><a class="header-anchor" href="#_3-数据获取的时序"><span>3. 数据获取的时序</span></a></h3><p>回到 [Video.vue](file:///g:/Save/Grogramming/Vue3/yike/src/views/Home/components/Video.vue) 的 <code>onBeforeMount</code>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">onBeforeMount</span><span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">await</span> <span class="token function">requireNew</span><span class="token punctuation">(</span>route<span class="token punctuation">.</span>params<span class="token punctuation">.</span>vid<span class="token punctuation">,</span> route<span class="token punctuation">.</span>params<span class="token punctuation">.</span>eid<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>requireNew</code> 里做了两件事：</p><ol><li>先拿到剧集元信息（vid、eid、title、img 封面图 → 这些很小）</li><li>再逐一拿到视频播放地址（<code>getVideoAdd</code> → CDN URL）</li></ol><p><strong>元信息先到，封面图先渲染 → 用户先看到图 → 视频地址后到 → 视频流最后加载。</strong></p><hr><h2 id="但这里有一个反模式-视频地址串行请求" tabindex="-1"><a class="header-anchor" href="#但这里有一个反模式-视频地址串行请求"><span>但这里有一个反模式：视频地址串行请求</span></a></h2><p>[handleVideo.js](file:///g:/Save/Grogramming/Vue3/yike/src/utils/handleVideo.js#L52-L66)：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span>videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> <span class="token constant">VIDEO_LIST_LENGTH</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> videoInfo <span class="token operator">=</span> <span class="token keyword">await</span> randomList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> add <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getVideoAdd</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">.</span>eid<span class="token punctuation">)</span>   <span class="token comment">// await 了 5 次</span></span>
<span class="line">    videoInfo<span class="token punctuation">.</span>url2 <span class="token operator">=</span> add</span>
<span class="line">    videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>已有的剧集元信息是 15 个（看 <code>getRandomList(limit=15)</code>），只需要 5 个。但获取这 5 个播放地址是 <strong>串行的</strong>——第 1 个地址返回了才开始请求第 2 个。如果每个请求 300ms，5 个就是 1.5 秒。</p><p><strong>应该改成 <code>Promise.all</code> 并行请求：</strong></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 应该的做法（伪代码）</span></span>
<span class="line"><span class="token keyword">const</span> videoInfos <span class="token operator">=</span> randomList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token constant">VIDEO_LIST_LENGTH</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">const</span> urls <span class="token operator">=</span> <span class="token keyword">await</span> Promise<span class="token punctuation">.</span><span class="token function">all</span><span class="token punctuation">(</span>videoInfos<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> <span class="token function">getVideoAdd</span><span class="token punctuation">(</span>v<span class="token punctuation">.</span>eid<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 一次等 5 个，总耗时 ≈ max(单个请求) 而不是 sum</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这就是为什么 <code>CLAUDE.md</code> 里标记了这个问题为&quot;已知优化点&quot;。</p><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p><strong>先加载什么：</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">UI 壳 → 封面图 → 播放器 SDK → 元信息 → 视频流</span>
<span class="line">  ↑                                    ↑</span>
<span class="line"> 0ms                              200-800ms</span>
<span class="line"> 用户立即看到&quot;有东西&quot;              用户看到画面动起来</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>永远不要让用户看到白屏。</strong> 哪怕你的视频流要等 3 秒，也要先用一个 loading 动画、一张封面图、一个骨架屏把空间填满。视频产品里，&quot;先加载壳&quot;是一个铁律——因为视频数据是最后一个到的，你不应该让它阻塞任何 UI 层的渲染。</p><h2 id="一、项目现状分析" tabindex="-1"><a class="header-anchor" href="#一、项目现状分析"><span>一、项目现状分析</span></a></h2><h3 id="_1-1-项目架构" tabindex="-1"><a class="header-anchor" href="#_1-1-项目架构"><span>1.1 项目架构</span></a></h3><ul><li><strong>框架</strong>: Vue 3 + Vite</li><li><strong>视频播放</strong>: Video.js (CDN加载)</li><li><strong>状态管理</strong>: Pinia</li><li><strong>组件结构</strong>:<div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Video.vue (容器 - 管理滑动切换)</span>
<span class="line">└── PlayBar.vue (播放器 - Video.js实例)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="_1-2-核心问题清单" tabindex="-1"><a class="header-anchor" href="#_1-2-核心问题清单"><span>1.2 核心问题清单</span></a></h3><table><thead><tr><th>优先级</th><th>问题</th><th>位置</th><th>影响</th></tr></thead><tbody><tr><td>P0</td><td>内存泄漏 - 不销毁video.js实例</td><td>PlayBar.vue</td><td>长时间使用页面崩溃</td></tr><tr><td>P1</td><td>视频串行加载慢</td><td>handleVideo.js</td><td>首屏加载时间长</td></tr><tr><td>P1</td><td>滚动性能差 - 触发重排</td><td>Video.vue</td><td>滑动卡顿</td></tr><tr><td>P2</td><td>事件冲突风险</td><td>Video.vue + PlayBar.vue</td><td>偶发交互异常</td></tr><tr><td>P2</td><td>硬编码mock数据</td><td>PlayBar.vue:72</td><td>可维护性差</td></tr></tbody></table><hr><h2 id="二、问题详解与解决方案" tabindex="-1"><a class="header-anchor" href="#二、问题详解与解决方案"><span>二、问题详解与解决方案</span></a></h2><h3 id="_2-1-滑动与点击事件冲突" tabindex="-1"><a class="header-anchor" href="#_2-1-滑动与点击事件冲突"><span>2.1 滑动与点击事件冲突</span></a></h3><h4 id="问题描述" tabindex="-1"><a class="header-anchor" href="#问题描述"><span>问题描述</span></a></h4><p>上下滑动切换视频时，可能误触发视频播放/暂停。</p><h4 id="当前实现" tabindex="-1"><a class="header-anchor" href="#当前实现"><span>当前实现</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// PlayBar.vue</span></span>
<span class="line"><span class="token keyword">let</span> isDragging <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token keyword">const</span> currentMoveThreshold <span class="token operator">=</span> <span class="token number">30</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">handleTouchStart</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    startX <span class="token operator">=</span> touch<span class="token punctuation">.</span>clientX</span>
<span class="line">    startY <span class="token operator">=</span> touch<span class="token punctuation">.</span>clientY</span>
<span class="line">    isDragging <span class="token operator">=</span> <span class="token boolean">false</span>  <span class="token comment">// 重置标志</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">handleTouchMove</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> distance <span class="token operator">=</span> Math<span class="token punctuation">.</span><span class="token function">sqrt</span><span class="token punctuation">(</span>deltaX <span class="token operator">*</span> deltaX <span class="token operator">+</span> deltaY <span class="token operator">*</span> deltaY<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>distance <span class="token operator">&gt;</span> currentMoveThreshold<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        isDragging <span class="token operator">=</span> <span class="token boolean">true</span>  <span class="token comment">// 超过阈值认为是滑动</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">handleTouchEnd</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>isDragging<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 点击才触发播放/暂停</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">paused</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">?</span> player<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">:</span> player<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="优化方案" tabindex="-1"><a class="header-anchor" href="#优化方案"><span>优化方案</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 统一使用 Pointer Events (推荐)</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">useGesture</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">startX</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">startY</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">startTime</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">isDragging</span><span class="token operator">:</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">const</span> <span class="token constant">TAP_THRESHOLD</span> <span class="token operator">=</span> <span class="token number">30</span>        <span class="token comment">// 像素</span></span>
<span class="line">    <span class="token keyword">const</span> <span class="token constant">TAP_TIME_THRESHOLD</span> <span class="token operator">=</span> <span class="token number">300</span>  <span class="token comment">// 毫秒</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">const</span> <span class="token function-variable function">onPointerDown</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        state<span class="token punctuation">.</span>startX <span class="token operator">=</span> e<span class="token punctuation">.</span>clientX</span>
<span class="line">        state<span class="token punctuation">.</span>startY <span class="token operator">=</span> e<span class="token punctuation">.</span>clientY</span>
<span class="line">        state<span class="token punctuation">.</span>startTime <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        state<span class="token punctuation">.</span>isDragging <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">const</span> <span class="token function-variable function">onPointerMove</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> dx <span class="token operator">=</span> e<span class="token punctuation">.</span>clientX <span class="token operator">-</span> state<span class="token punctuation">.</span>startX</span>
<span class="line">        <span class="token keyword">const</span> dy <span class="token operator">=</span> e<span class="token punctuation">.</span>clientY <span class="token operator">-</span> state<span class="token punctuation">.</span>startY</span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>Math<span class="token punctuation">.</span><span class="token function">sqrt</span><span class="token punctuation">(</span>dx <span class="token operator">*</span> dx <span class="token operator">+</span> dy <span class="token operator">*</span> dy<span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token constant">TAP_THRESHOLD</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            state<span class="token punctuation">.</span>isDragging <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">const</span> <span class="token function-variable function">onPointerUp</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> duration <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> state<span class="token punctuation">.</span>startTime</span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>state<span class="token punctuation">.</span>isDragging <span class="token operator">&amp;&amp;</span> duration <span class="token operator">&lt;</span> <span class="token constant">TAP_TIME_THRESHOLD</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 确认是点击</span></span>
<span class="line">            <span class="token function">handleTap</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span> onPointerDown<span class="token punctuation">,</span> onPointerMove<span class="token punctuation">,</span> onPointerUp <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Pointer Events（指针事件）是前端开发中一套<strong>统一的 DOM 事件模型</strong>，专门用来处理各种指针输入设备，比如鼠标、触控笔、单点或多点的手指触摸等。</p><p>简单来说，它的出现就是为了解决过去前端开发中“鼠标事件（Mouse Events）”和“触摸事件（Touch Events）”两套逻辑并存、需要分别维护的痛点。有了 Pointer Events，开发者可以**“一次编写，多端运行”**，无论是 PC 端还是移动端，都能用同一套代码完美处理拖拽、点击等交互。</p><p>结合你提供的代码，我来为你详细拆解一下它的核心概念以及你这段代码的精妙之处：</p><h3 id="🎯-为什么推荐使用-pointer-events" tabindex="-1"><a class="header-anchor" href="#🎯-为什么推荐使用-pointer-events"><span>🎯 为什么推荐使用 Pointer Events？</span></a></h3><p>在 Pointer Events 出现之前，如果你想写一个拖拽功能，通常需要同时监听 <code>mousedown/mousemove/mouseup</code>（给电脑用）和 <code>touchstart/touchmove/touchend</code>（给手机用）。而 Pointer Events 将它们统一成了语义完全相同的事件：</p><ul><li><code>pointerdown</code>：代替了 <code>mousedown</code> 和 <code>touchstart</code></li><li><code>pointermove</code>：代替了 <code>mousemove</code> 和 <code>touchmove</code></li><li><code>pointerup</code>：代替了 <code>mouseup</code> 和 <code>touchend</code></li></ul><h3 id="💡-你的代码在做什么-精准的手势识别" tabindex="-1"><a class="header-anchor" href="#💡-你的代码在做什么-精准的手势识别"><span>💡 你的代码在做什么？（精准的手势识别）</span></a></h3><p>你提供的 <code>useGesture</code> 代码是一个非常经典的**“区分点击与拖拽”**的实战案例。它的核心逻辑在于：</p><ol><li><strong>记录起点</strong>：在 <code>onPointerDown</code> 时，记录下手指或鼠标按下的初始坐标 (<code>startX</code>, <code>startY</code>) 和时间 (<code>startTime</code>)。</li><li><strong>判断拖拽</strong>：在 <code>onPointerMove</code> 时，计算当前移动的距离。如果移动距离超过了 <code>TAP_THRESHOLD</code>（30像素），就认定用户是在“拖拽”，而不是“点击”。</li><li><strong>确认点击</strong>：在 <code>onPointerUp</code> 时，只有当 <code>isDragging</code> 为 <code>false</code>（没怎么移动）<strong>且</strong> 按下时间小于 <code>TAP_TIME_THRESHOLD</code>（300毫秒）时，才触发 <code>handleTap()</code>。这完美避免了“拖拽结束时误触点击”的常见 Bug。</li></ol><h3 id="🚀-代码优化建议-加上-指针捕获" tabindex="-1"><a class="header-anchor" href="#🚀-代码优化建议-加上-指针捕获"><span>🚀 代码优化建议：加上“指针捕获”</span></a></h3><p>虽然你的代码逻辑已经很清晰，但在实际拖拽场景中，如果用户的手指/鼠标移动速度过快，移出了元素本身，浏览器可能会丢失 <code>pointermove</code> 和 <code>pointerup</code> 的监听。</p><p>Pointer Events 提供了一个非常强大的 API：<code>setPointerCapture</code>。建议在 <code>onPointerDown</code> 中加上它，确保即使指针移出元素边界，事件依然能被捕获：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">onPointerDown</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 记录初始状态...</span></span>
<span class="line">    state<span class="token punctuation">.</span>startX <span class="token operator">=</span> e<span class="token punctuation">.</span>clientX</span>
<span class="line">    state<span class="token punctuation">.</span>startY <span class="token operator">=</span> e<span class="token punctuation">.</span>clientY</span>
<span class="line">    state<span class="token punctuation">.</span>startTime <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    state<span class="token punctuation">.</span>isDragging <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 【新增优化】锁定当前指针，确保快速拖拽时不会丢失 pointerup 事件</span></span>
<span class="line">    e<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">setPointerCapture</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>pointerId<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">onPointerUp</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 处理点击逻辑...</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>state<span class="token punctuation">.</span>isDragging <span class="token operator">&amp;&amp;</span> duration <span class="token operator">&lt;</span> <span class="token constant">TAP_TIME_THRESHOLD</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">handleTap</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 【新增优化】释放指针锁定</span></span>
<span class="line">    e<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">releasePointerCapture</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>pointerId<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="📊-pointer-events-的独有优势" tabindex="-1"><a class="header-anchor" href="#📊-pointer-events-的独有优势"><span>📊 Pointer Events 的独有优势</span></a></h3><p>除了统一事件，它还提供了很多传统鼠标事件没有的专属属性，方便你做更精细的交互（比如画画应用）：</p><ul><li><strong><code>e.pointerType</code></strong>：可以直接判断用户是用 <code>mouse</code>（鼠标）、<code>touch</code>（手指）还是 <code>pen</code>（触控笔）在操作，从而给出不同的 UI 反馈。</li><li><strong><code>e.pressure</code></strong>：能获取按压的力度（0到1之间），常用于手写笔压感。</li><li><strong><code>e.pointerId</code></strong>：每个触点都有唯一的 ID，是实现<strong>多点触控</strong>（比如双指缩放、旋转）的基础。</li></ul><p>目前主流浏览器（Chrome, Firefox, Safari, Edge）都已经广泛支持 Pointer Events，在 2026 年的今天，它绝对是处理前端交互的首选方案。</p><hr><p>要不要我把优化后的完整代码整理出来，方便你直接复制到项目里用？</p><hr><h3 id="_2-2-内存泄漏-核心问题" tabindex="-1"><a class="header-anchor" href="#_2-2-内存泄漏-核心问题"><span>2.2 内存泄漏（核心问题）</span></a></h3><h4 id="问题代码" tabindex="-1"><a class="header-anchor" href="#问题代码"><span>问题代码</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// PlayBar.vue - 只创建不销毁</span></span>
<span class="line"><span class="token function">onMounted</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    player <span class="token operator">=</span> window<span class="token punctuation">.</span><span class="token function">videojs</span><span class="token punctuation">(</span>props<span class="token punctuation">.</span>videoInfo<span class="token punctuation">,</span> options<span class="token punctuation">)</span></span>
<span class="line">    player<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&#39;play&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    player<span class="token punctuation">.</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string">&#39;ended&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// ❌ 缺少 onBeforeUnmount</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="修复方案" tabindex="-1"><a class="header-anchor" href="#修复方案"><span>修复方案</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> onBeforeUnmount <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;vue&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">onBeforeUnmount</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>player<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 1. 移除所有事件监听</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">off</span><span class="token punctuation">(</span><span class="token string">&#39;play&#39;</span><span class="token punctuation">)</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">off</span><span class="token punctuation">(</span><span class="token string">&#39;pause&#39;</span><span class="token punctuation">)</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">off</span><span class="token punctuation">(</span><span class="token string">&#39;ended&#39;</span><span class="token punctuation">)</span></span>
<span class="line">        </span>
<span class="line">        <span class="token comment">// 2. 暂停播放</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        </span>
<span class="line">        <span class="token comment">// 3. 销毁实例 (会清理DOM和事件)</span></span>
<span class="line">        player<span class="token punctuation">.</span><span class="token function">dispose</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        player <span class="token operator">=</span> <span class="token keyword">null</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="内存泄漏检测方法" tabindex="-1"><a class="header-anchor" href="#内存泄漏检测方法"><span>内存泄漏检测方法</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// Chrome DevTools 检测步骤:</span></span>
<span class="line"><span class="token comment">// 1. Performance → Record → 执行滑动操作 → Stop</span></span>
<span class="line"><span class="token comment">// 2. Memory → Take Heap Snapshot</span></span>
<span class="line"><span class="token comment">// 3. 对比多次操作后的内存占用</span></span>
<span class="line"><span class="token comment">// 4. 搜索 detached 查看游离DOM</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 代码中临时检测</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>window<span class="token punctuation">.</span>performance <span class="token operator">&amp;&amp;</span> performance<span class="token punctuation">.</span>memory<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Used JS Heap:&#39;</span><span class="token punctuation">,</span> performance<span class="token punctuation">.</span>memory<span class="token punctuation">.</span>usedJSHeapSize <span class="token operator">/</span> <span class="token number">1048576</span><span class="token punctuation">,</span> <span class="token string">&#39;MB&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="_2-3-自动播放机制" tabindex="-1"><a class="header-anchor" href="#_2-3-自动播放机制"><span>2.3 自动播放机制</span></a></h3><h4 id="当前实现-1" tabindex="-1"><a class="header-anchor" href="#当前实现-1"><span>当前实现</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// Video.vue - 同时渲染5个视频，通过Playing控制</span></span>
<span class="line"><span class="token operator">&lt;</span>PlayBar</span>
<span class="line">    v<span class="token operator">-</span><span class="token keyword">for</span><span class="token operator">=</span><span class="token string">&quot;(video, index) in videoInfoList&quot;</span></span>
<span class="line">    <span class="token operator">:</span>key<span class="token operator">=</span><span class="token string">&quot;video.eid&quot;</span></span>
<span class="line">    <span class="token operator">:</span>Playing<span class="token operator">=</span><span class="token string">&quot;index == curIndex&quot;</span></span>
<span class="line"><span class="token operator">/</span><span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="面试点-为什么需要用户交互后才能播放" tabindex="-1"><a class="header-anchor" href="#面试点-为什么需要用户交互后才能播放"><span>面试点：为什么需要用户交互后才能播放？</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 浏览器自动播放策略 (Autoplay Policy)</span></span>
<span class="line"><span class="token comment">// Chrome 66+ 要求：</span></span>
<span class="line"><span class="token comment">// 1. 静音视频可以自动播放</span></span>
<span class="line"><span class="token comment">// 2. 用户与域名有过交互后可以播放有声视频</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 最佳实践</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">autoPlay</span> <span class="token operator">=</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter">player</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">await</span> player<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 自动播放被阻止，显示播放按钮</span></span>
<span class="line">        showPlayButton <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 检测自动播放权限</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">canAutoPlay</span> <span class="token operator">=</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> video <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;video&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    video<span class="token punctuation">.</span>muted <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">await</span> video<span class="token punctuation">.</span><span class="token function">play</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="_2-4-视频队列与预加载" tabindex="-1"><a class="header-anchor" href="#_2-4-视频队列与预加载"><span>2.4 视频队列与预加载</span></a></h3><h4 id="当前问题-串行加载慢" tabindex="-1"><a class="header-anchor" href="#当前问题-串行加载慢"><span>当前问题：串行加载慢</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// handleVideo.js - 串行加载（慢）</span></span>
<span class="line"><span class="token keyword">while</span> <span class="token punctuation">(</span>videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length <span class="token operator">&lt;</span> <span class="token constant">VIDEO_LIST_LENGTH</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> videoInfo <span class="token operator">=</span> <span class="token keyword">await</span> randomList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">const</span> add <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getVideoAdd</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">.</span>eid<span class="token punctuation">)</span>  <span class="token comment">// 等待每个请求</span></span>
<span class="line">    videoInfo<span class="token punctuation">.</span>url2 <span class="token operator">=</span> add</span>
<span class="line">    videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="优化-并行加载" tabindex="-1"><a class="header-anchor" href="#优化-并行加载"><span>优化：并行加载</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 优化后 - 并行加载（快5倍）</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">loadVideosParallel</span> <span class="token operator">=</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> videosToLoad <span class="token operator">=</span> <span class="token function">Array</span><span class="token punctuation">(</span><span class="token constant">VIDEO_LIST_LENGTH</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> randomList<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">pop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">const</span> loadedVideos <span class="token operator">=</span> <span class="token keyword">await</span> Promise<span class="token punctuation">.</span><span class="token function">all</span><span class="token punctuation">(</span></span>
<span class="line">        videosToLoad<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter">videoInfo</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">const</span> url <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getVideoAdd</span><span class="token punctuation">(</span>videoInfo<span class="token punctuation">.</span>eid<span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token operator">...</span>videoInfo<span class="token punctuation">,</span> <span class="token literal-property property">url2</span><span class="token operator">:</span> url <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line">    </span>
<span class="line">    videoInfoList<span class="token punctuation">.</span>value <span class="token operator">=</span> loadedVideos</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="进阶-预加载策略" tabindex="-1"><a class="header-anchor" href="#进阶-预加载策略"><span>进阶：预加载策略</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 预加载下一个视频</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">preloadNextVideo</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">currentIndex</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> nextIndex <span class="token operator">=</span> currentIndex <span class="token operator">+</span> <span class="token number">1</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>nextIndex <span class="token operator">&lt;</span> videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> nextVideo <span class="token operator">=</span> videoInfoList<span class="token punctuation">.</span>value<span class="token punctuation">[</span>nextIndex<span class="token punctuation">]</span></span>
<span class="line">        <span class="token keyword">const</span> link <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;link&#39;</span><span class="token punctuation">)</span></span>
<span class="line">        link<span class="token punctuation">.</span>rel <span class="token operator">=</span> <span class="token string">&#39;preload&#39;</span></span>
<span class="line">        link<span class="token punctuation">.</span>href <span class="token operator">=</span> nextVideo<span class="token punctuation">.</span>url2</span>
<span class="line">        link<span class="token punctuation">.</span>as <span class="token operator">=</span> <span class="token string">&#39;video&#39;</span></span>
<span class="line">        document<span class="token punctuation">.</span>head<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>link<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h3 id="_2-5-滚动性能优化" tabindex="-1"><a class="header-anchor" href="#_2-5-滚动性能优化"><span>2.5 滚动性能优化</span></a></h3><h4 id="当前问题" tabindex="-1"><a class="header-anchor" href="#当前问题"><span>当前问题</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// Video.vue - scrollTo 触发重排 (Reflow)</span></span>
<span class="line">videoElement<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">scrollTo</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">top</span><span class="token operator">:</span> curIndex<span class="token punctuation">.</span>value <span class="token operator">*</span> videoHeight<span class="token punctuation">,</span>  <span class="token comment">// 读取再写入</span></span>
<span class="line">    <span class="token literal-property property">behavior</span><span class="token operator">:</span> <span class="token string">&#39;smooth&#39;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="优化方案-使用-transform-gpu加速" tabindex="-1"><a class="header-anchor" href="#优化方案-使用-transform-gpu加速"><span>优化方案：使用 Transform（GPU加速）</span></a></h4><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// CSS</span></span>
<span class="line"><span class="token punctuation">.</span>video<span class="token operator">-</span>wrapper <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">transform</span><span class="token operator">:</span> <span class="token function">translateY</span><span class="token punctuation">(</span><span class="token keyword">var</span><span class="token punctuation">(</span><span class="token operator">--</span>offset<span class="token operator">-</span>y<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token literal-property property">transition</span><span class="token operator">:</span> transform <span class="token number">0</span><span class="token punctuation">.</span>3s ease<span class="token punctuation">;</span></span>
<span class="line">    will<span class="token operator">-</span>change<span class="token operator">:</span> transform<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// JS</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">scrollToCurrent</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">index</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> offset <span class="token operator">=</span> <span class="token operator">-</span>index <span class="token operator">*</span> <span class="token number">100</span>  <span class="token comment">// vh单位</span></span>
<span class="line">    videoWrapper<span class="token punctuation">.</span>value<span class="token punctuation">.</span>style<span class="token punctuation">.</span><span class="token function">setProperty</span><span class="token punctuation">(</span><span class="token string">&#39;--offset-y&#39;</span><span class="token punctuation">,</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>offset<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">vh</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="为什么-transform-比-scrolltop-快" tabindex="-1"><a class="header-anchor" href="#为什么-transform-比-scrolltop-快"><span>为什么 transform 比 scrollTop 快？</span></a></h4><ul><li><code>scrollTop</code>：触发布局计算（Layout）→ 绘制（Paint）→ 合成（Composite）</li><li><code>transform</code>：直接合成层（Composite），跳过布局和绘制</li></ul><hr><h2 id="三、面试常见问题" tabindex="-1"><a class="header-anchor" href="#三、面试常见问题"><span>三、面试常见问题</span></a></h2><h3 id="q1-移动端视频播放有哪些兼容性问题" tabindex="-1"><a class="header-anchor" href="#q1-移动端视频播放有哪些兼容性问题"><span>Q1: 移动端视频播放有哪些兼容性问题？</span></a></h3><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line"><span class="token list punctuation">1.</span> <span class="token bold"><span class="token punctuation">**</span><span class="token content">全屏问题</span><span class="token punctuation">**</span></span></span>
<span class="line">   <span class="token list punctuation">-</span> iOS：强制全屏播放，无法禁止</span>
<span class="line">   <span class="token list punctuation">-</span> 解决：使用 inline 属性 + playsinline</span>
<span class="line">   \`\`\`html</span>
<span class="line">   <span class="token entity named-entity" title="&lt;">&amp;lt;</span>video playsinline webkit-playsinline x5-playsinline<span class="token entity named-entity" title="&gt;">&amp;gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li><p><strong>自动播放</strong></p><ul><li>微信内置浏览器：首次必须用户点击</li><li>解决：监听 WeixinJSBridgeReady</li></ul></li><li><p><strong>层级问题</strong></p><ul><li>安卓：视频默认置顶，会覆盖其他元素</li><li>解决：使用 cover-view 或同层播放器</li></ul></li><li><p><strong>黑屏/白屏</strong></p><ul><li>原因：视频编码不支持（如H.265）</li><li>解决：提供多格式源或转码</li></ul></li></ol><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"></span>
<span class="line">### Q2: 如何设计一个流畅的短视频滑动组件？</span>
<span class="line"></span>
<span class="line">\`\`\`markdown</span>
<span class="line">1. **渲染优化**</span>
<span class="line">   - 虚拟列表：只渲染当前+前后各1个视频（3个）</span>
<span class="line">   - 回收复用：滑动后销毁移出屏幕的视频</span>
<span class="line"></span>
<span class="line">2. **内存优化**</span>
<span class="line">   - 限制同时存在的video实例数（建议3-5个）</span>
<span class="line">   - 及时调用 dispose() 销毁播放器</span>
<span class="line">   - 使用对象池复用播放器实例</span>
<span class="line"></span>
<span class="line">3. **加载优化**</span>
<span class="line">   - 首屏只加载当前视频</span>
<span class="line">   - 预加载下一个视频（静音+暂停）</span>
<span class="line">   - 使用 HTTP Range 请求分段加载</span>
<span class="line"></span>
<span class="line">4. **交互优化**</span>
<span class="line">   - 滑动距离阈值（如80px）才切换</span>
<span class="line">   - 滑动速度检测（快速滑动直接切换）</span>
<span class="line">   - 吸附效果（snap）</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q3-video-js-和原生-video-各有什么优缺点" tabindex="-1"><a class="header-anchor" href="#q3-video-js-和原生-video-各有什么优缺点"><span>Q3: video.js 和原生 video 各有什么优缺点？</span></a></h3><table><thead><tr><th>特性</th><th>Video.js</th><th>原生 video</th></tr></thead><tbody><tr><td>UI定制</td><td>丰富，可自定义皮肤</td><td>有限，各浏览器不同</td></tr><tr><td>插件生态</td><td>丰富（广告、统计等）</td><td>无</td></tr><tr><td>体积</td><td>较大（需额外加载）</td><td>无额外体积</td></tr><tr><td>学习成本</td><td>需要学习API</td><td>直接使用</td></tr><tr><td>移动端</td><td>可能需要适配</td><td>原生支持好</td></tr><tr><td>直播支持</td><td>HLS/DASH 支持好</td><td>有限</td></tr></tbody></table><h3 id="q4-视频首屏加载慢怎么优化" tabindex="-1"><a class="header-anchor" href="#q4-视频首屏加载慢怎么优化"><span>Q4: 视频首屏加载慢怎么优化？</span></a></h3><div class="language-markdown line-numbers-mode" data-highlighter="prismjs" data-ext="md"><pre><code class="language-markdown"><span class="line"><span class="token list punctuation">1.</span> <span class="token bold"><span class="token punctuation">**</span><span class="token content">视频本身优化</span><span class="token punctuation">**</span></span></span>
<span class="line">   <span class="token list punctuation">-</span> 压缩视频（FFmpeg转码）</span>
<span class="line">   <span class="token list punctuation">-</span> 使用 CDN 分发</span>
<span class="line">   <span class="token list punctuation">-</span> 自适应码率（根据网络选择清晰度）</span>
<span class="line"></span>
<span class="line"><span class="token list punctuation">2.</span> <span class="token bold"><span class="token punctuation">**</span><span class="token content">加载策略</span><span class="token punctuation">**</span></span></span>
<span class="line">   <span class="token list punctuation">-</span> 封面图占位（poster属性）</span>
<span class="line">   <span class="token list punctuation">-</span> 懒加载：进入视口才加载视频</span>
<span class="line">   <span class="token list punctuation">-</span> 分段加载（HTTP 206 Partial Content）</span>
<span class="line"></span>
<span class="line"><span class="token list punctuation">3.</span> <span class="token bold"><span class="token punctuation">**</span><span class="token content">用户体验</span><span class="token punctuation">**</span></span></span>
<span class="line">   <span class="token list punctuation">-</span> 显示加载进度</span>
<span class="line">   <span class="token list punctuation">-</span> 先播放低清晰度版本，再切换高清</span>
<span class="line">   <span class="token list punctuation">-</span> 预加载策略：preload=&quot;metadata&quot; 只加载元数据</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q5-如何检测视频卡顿" tabindex="-1"><a class="header-anchor" href="#q5-如何检测视频卡顿"><span>Q5: 如何检测视频卡顿？</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 方法1：检测播放帧率</span></span>
<span class="line"><span class="token keyword">let</span> lastTime <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">let</span> frameCount <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">checkStutter</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> now <span class="token operator">=</span> performance<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    frameCount<span class="token operator">++</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>now <span class="token operator">-</span> lastTime <span class="token operator">&gt;=</span> <span class="token number">1000</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> fps <span class="token operator">=</span> frameCount</span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>fps <span class="token operator">&lt;</span> <span class="token number">20</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            console<span class="token punctuation">.</span><span class="token function">warn</span><span class="token punctuation">(</span><span class="token string">&#39;视频卡顿，FPS:&#39;</span><span class="token punctuation">,</span> fps<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        frameCount <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line">        lastTime <span class="token operator">=</span> now</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">requestAnimationFrame</span><span class="token punctuation">(</span>checkStutter<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方法2：检测 buffered 进度</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">checkBuffering</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">video</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> buffered <span class="token operator">=</span> video<span class="token punctuation">.</span>buffered</span>
<span class="line">    <span class="token keyword">const</span> currentTime <span class="token operator">=</span> video<span class="token punctuation">.</span>currentTime</span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 查找当前时间是否在已缓冲范围内</span></span>
<span class="line">    <span class="token keyword">let</span> isBuffered <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> buffered<span class="token punctuation">.</span>length<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>currentTime <span class="token operator">&gt;=</span> buffered<span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> currentTime <span class="token operator">&lt;=</span> buffered<span class="token punctuation">.</span><span class="token function">end</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            isBuffered <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">            <span class="token keyword">break</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>isBuffered<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;正在缓冲...&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方法3：监听 waiting 事件</span></span>
<span class="line">video<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;waiting&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;视频因缓冲暂停&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">video<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;playing&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;视频恢复播放&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、修复计划" tabindex="-1"><a class="header-anchor" href="#四、修复计划"><span>四、修复计划</span></a></h2><h3 id="phase-1-紧急修复-内存泄漏" tabindex="-1"><a class="header-anchor" href="#phase-1-紧急修复-内存泄漏"><span>Phase 1: 紧急修复（内存泄漏）</span></a></h3><ul><li>[ ] 在 PlayBar.vue 添加 onBeforeUnmount 钩子</li><li>[ ] 调用 player.dispose() 销毁实例</li><li>[ ] 测试内存占用变化</li></ul><h3 id="phase-2-性能优化" tabindex="-1"><a class="header-anchor" href="#phase-2-性能优化"><span>Phase 2: 性能优化</span></a></h3><ul><li>[ ] handleVideo.js 串行改并行加载</li><li>[ ] Video.vue scrollTo 改为 transform</li><li>[ ] 添加视频预加载逻辑</li></ul><h3 id="phase-3-体验优化" tabindex="-1"><a class="header-anchor" href="#phase-3-体验优化"><span>Phase 3: 体验优化</span></a></h3><ul><li>[ ] 统一手势判断逻辑</li><li>[ ] 添加加载状态提示</li><li>[ ] 优化首屏加载速度</li></ul><hr><h2 id="五、相关链接" tabindex="-1"><a class="header-anchor" href="#五、相关链接"><span>五、相关链接</span></a></h2><ul><li><a href="https://docs.videojs.com/" target="_blank" rel="noopener noreferrer">Video.js 文档</a></li><li><a href="https://developer.chrome.com/blog/autoplay/" target="_blank" rel="noopener noreferrer">Chrome 自动播放策略</a></li><li><a href="https://web.dev/optimize-lcp/" target="_blank" rel="noopener noreferrer">Web 视频性能优化</a></li></ul>`,203)])])}const c=s(t,[["render",l]]),u=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E9%9D%A2%E8%AF%95/%E9%A1%B9%E7%9B%AE/%E4%B8%80%E5%88%BB/%E4%B8%80%E5%88%BB%E7%9F%AD%E5%89%A7.html","title":"视频播放器交互设计与性能优化 - 面试准备文档","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/面试/项目/一刻/一刻短剧.md"}');export{c as comp,u as data};
